-- Apply after the V7 migrations. No existing leadership is overwritten.
begin;
create or replace function public.save_ddpe_leadership(p_value jsonb,p_actor uuid,p_version timestamptz)
returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare current_version timestamptz;
begin
 if not exists(select 1 from public.ddpe_permissions where user_id=p_actor and permission='content_editor' and scope_type='organization' and scope_id is null) then raise exception 'forbidden'; end if;
 if jsonb_typeof(p_value->'members') is distinct from 'array' then raise exception 'invalid_leadership'; end if;
 perform pg_advisory_xact_lock(hashtextextended('leadership',0));
 select updated_at into current_version from public.site_settings where setting_key='leadership' for update;
 if current_version is distinct from p_version then raise exception 'cms_conflict'; end if;
 insert into public.site_settings(setting_key,value,is_public,updated_by,updated_at) values('leadership',p_value,true,p_actor,clock_timestamp())
 on conflict(setting_key) do update set value=excluded.value,is_public=true,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
 insert into public.ddpe_audit_log(actor_id,action,entity_type,entity_id,details) values(p_actor,'leadership_saved','site_setting','leadership',jsonb_build_object('member_count',jsonb_array_length(p_value->'members')));
end $$;
revoke all on function public.save_ddpe_leadership(jsonb,uuid,timestamptz) from public,anon,authenticated;
grant execute on function public.save_ddpe_leadership(jsonb,uuid,timestamptz) to service_role;
